void Require(bool ok, const char* message) { if (!ok) throw std::runtime_error(message); }
struct VkFailure : std::runtime_error { VkResult result; VkFailure(VkResult value,const char* message):std::runtime_error(message),result(value){} };
struct Json {
    enum Kind { Null, Boolean, Number, StringValue, Array, Object } kind = Null;
    std::string text;
    std::vector<Json> array;
    std::map<std::string,Json> object;
    Json() = default;
    Json(bool b) : kind(Boolean), text(b ? "true" : "false") {}
    Json(uint64_t n) : kind(Number), text(std::to_string(n)) {}
    Json(int32_t n) : kind(Number), text(std::to_string(n)) {}
    Json(double n) : kind(Number), text(std::to_string(n)) { Require(std::isfinite(n), "Nonfinite JSON number"); }
    Json(const std::string& s) : kind(StringValue), text(s) {}
    Json(const char* s) : kind(StringValue), text(s) {}
    static Json Arr() { Json j; j.kind=Array; return j; }
    static Json Obj() { Json j; j.kind=Object; return j; }
    Json& operator[](const std::string& key) { kind=Object; return object[key]; }
    const Json& at(const std::string& key) const { Require(kind==Object,"Expected JSON object"); return object.at(key); }
    uint64_t u64() const { uint64_t n=0; auto r=std::from_chars(text.data(),text.data()+text.size(),n); Require(kind==Number&&r.ec==std::errc{}&&r.ptr==text.data()+text.size(),"Expected unsigned JSON integer"); return n; }
    std::string str() const { Require(kind==StringValue,"Expected JSON string"); return text; }
};
std::string Quote(const std::string& value) {
    static constexpr char hex[]="0123456789abcdef"; std::string out="\"";
    for(unsigned char c:value) { if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=hex[c>>4];out+=hex[c&15];}else out+=char(c); } return out+'"';
}
std::string Dump(const Json& value) {
    if(value.kind==Json::Null)return "null";
    if(value.kind==Json::StringValue)return Quote(value.text);
    if(value.kind==Json::Boolean||value.kind==Json::Number)return value.text;
    std::string result=value.kind==Json::Array?"[":"{"; bool first=true;
    if(value.kind==Json::Array)for(const auto& item:value.array){if(!first)result+=',';first=false;result+=Dump(item);}
    else for(const auto& [key,item]:value.object){if(!first)result+=',';first=false;result+=Quote(key)+':'+Dump(item);}
    return result+(value.kind==Json::Array?"]":"}");
}
