bool Hash(const std::string& hash){return hash.size()==64&&hash.find_first_not_of("0123456789abcdef")==std::string::npos;}
template<class T,class Call> std::vector<T> Enumerate(Call call,uint32_t maximum=4096){
    for(int retry=0;retry<4;++retry){uint32_t count=0;VkResult result=call(&count,nullptr);if(result!=VK_SUCCESS&&result!=VK_INCOMPLETE)throw VkFailure(result,"Vulkan enumeration count failed");Require(count<=maximum,"Vulkan enumeration admission exceeded");std::vector<T> items(count);if(!count)return items;const auto capacity=count;result=call(&count,items.data());Require(count<=capacity,"Vulkan enumeration capacity changed");if(result==VK_SUCCESS){items.resize(count);return items;}if(result!=VK_INCOMPLETE)throw VkFailure(result,"Vulkan enumeration data failed");}throw VkFailure(VK_INCOMPLETE,"Vulkan enumeration did not stabilize");
}
struct ProbeScope {
    VulkanFunctions functions; VkInstance instance=VK_NULL_HANDLE; VkSurfaceKHR surface=VK_NULL_HANDLE;
    ~ProbeScope(){if(surface&&functions.vkDestroySurfaceKHR)functions.vkDestroySurfaceKHR(instance,surface,nullptr);if(instance&&functions.vkDestroyInstance)functions.vkDestroyInstance(instance,nullptr);}
};
const std::vector<std::string>& DefaultShaders(){static const std::vector<std::string> names={"splat_preprocess.spv","splat_prefix_sum.spv","splat_prepare_dispatch.spv","splat_assign_keys.spv","splat_radix_histogram.spv","splat_radix_offsets.spv","splat_radix_scatter.spv","splat_tile_boundaries.spv","splat_render.spv","splat_present.vert.spv","splat_present.frag.spv"};return names;}
bool Capability(uint32_t cap,const VkPhysicalDeviceFeatures& features,const VkPhysicalDeviceSubgroupProperties& subgroup,bool float16){
    switch(cap){case 1:case 50:return true;case 9:return float16;case 10:return features.shaderFloat64;case 11:return features.shaderInt64;case 49:return features.shaderStorageImageExtendedFormats;case 55:return features.shaderStorageImageReadWithoutFormat;case 56:return features.shaderStorageImageWriteWithoutFormat;default:break;}
    if(cap>=61&&cap<=68){const VkSubgroupFeatureFlags operations[]={VK_SUBGROUP_FEATURE_BASIC_BIT,VK_SUBGROUP_FEATURE_VOTE_BIT,VK_SUBGROUP_FEATURE_ARITHMETIC_BIT,VK_SUBGROUP_FEATURE_BALLOT_BIT,VK_SUBGROUP_FEATURE_SHUFFLE_BIT,VK_SUBGROUP_FEATURE_SHUFFLE_RELATIVE_BIT,VK_SUBGROUP_FEATURE_CLUSTERED_BIT,VK_SUBGROUP_FEATURE_QUAD_BIT};return (subgroup.supportedStages&VK_SHADER_STAGE_COMPUTE_BIT)&&(subgroup.supportedOperations&operations[cap-61]);}return false;
}
Json Identity(const FAndroidProbeIdentity& i){Json j=Json::Obj();j["application"]=i.application.substr(0,4096);j["build"]=i.build.substr(0,4096);j["workspace"]=i.workspace.substr(0,4096);j["abi"]=i.abi.substr(0,256);j["apkSHA256"]=Hash(i.apkSHA256)?Json(i.apkSHA256):Json();j["nativeSHA256"]=Hash(i.nativeSHA256)?Json(i.nativeSHA256):Json();j["configSHA256"]=Hash(i.configSHA256)?Json(i.configSHA256):Json();j["emulator"]=i.emulator?Json(*i.emulator):Json();j["translated"]=i.translated?Json(*i.translated):Json();return j;}
