FAndroidShaderRequirements FAndroidCapabilities::ParseShaderRequirements(const std::string& manifest,const std::vector<std::string>& selected,std::string& error){
    FAndroidShaderRequirements out;
    try{auto root=Parser(manifest).parse();Require(root.at("schemaVersion").u64()==1&&root.at("targetEnvironment").str()=="vulkan1.2","Unsupported shader manifest schema/environment");const auto& shaders=root.at("shaders");Require(shaders.kind==Json::Array&&shaders.array.size()<=256,"Invalid shader inventory");const auto& names=selected.empty()?DefaultShaders():selected;Require(!names.empty()&&names.size()<=256,"Invalid active shader selection");std::set<std::string> wanted(names.begin(),names.end()),found,all;std::set<uint32_t> capabilities;for(const auto& shader:shaders.array){const auto name=shader.at("path").str();Require(all.insert(name).second,"Duplicate shader manifest entry");if(!wanted.count(name))continue;found.insert(name);Require(Hash(shader.at("sha256").str())&&shader.at("bytes").u64()>0,"Invalid SPIR-V artifact identity");const auto& requirements=shader.at("requirements");const auto& caps=requirements.at("capabilities");Require(caps.kind==Json::Array&&caps.array.size()<=256,"Invalid SPIR-V capabilities");for(const auto& cap:caps.array){auto value=cap.u64();Require(value<=UINT32_MAX,"SPIR-V capability overflow");capabilities.insert(uint32_t(value));}const auto& sizes=requirements.at("localSizes");Require(sizes.kind==Json::Array&&sizes.array.size()<=16,"Invalid SPIR-V workgroups");Require(!sizes.array.empty()||name.ends_with(".vert.spv")||name.ends_with(".frag.spv"),"Compute shader local size absent");for(const auto& group:sizes.array){Require(group.kind==Json::Array&&group.array.size()==3,"Invalid local size dimensions");uint64_t invocations=1;for(size_t axis=0;axis<3;++axis){const auto n=group.array[axis].u64();Require(n>0&&n<=65536&&invocations<=UINT64_MAX/n,"Invalid workgroup size");out.localSize[axis]=std::max(out.localSize[axis],uint32_t(n));invocations*=n;}out.maxInvocations=std::max(out.maxInvocations,invocations);}out.sharedMemoryBytes=std::max(out.sharedMemoryBytes,requirements.at("sharedMemoryBytesUpperBound").u64());}Require(found==wanted,"Active shader absent from final SPIR-V inventory");Require(capabilities.count(1)!=0,"SPIR-V Shader capability absent");out.capabilities.assign(capabilities.begin(),capabilities.end());out.shaderInt64=capabilities.count(11)!=0;out.shaderFloat64=capabilities.count(10)!=0;out.shaderFloat16=capabilities.count(9)!=0;std::vector<uint8_t> bytes(manifest.begin(),manifest.end());out.shaderIdentity=FSplatSceneFormat::SHA256(bytes);out.valid=true;error.clear();return out;}catch(const std::exception& e){error=e.what();return {};}
}

