bool FAndroidCapabilities::MatchPhysicalDevice(const FAndroidCapabilityReport& report,
    const FAndroidPhysicalDeviceIdentity& identity,uint32_t& reportIndex,std::string& error,bool requireRenderEligible) {
    try {
        Require(!identity.name.empty()&&identity.name.size()<=VK_MAX_PHYSICAL_DEVICE_NAME_SIZE,"Invalid selected device identity");
        Require(identity.deviceUUID.empty()||(identity.deviceUUID.size()==32&&identity.deviceUUID.find_first_not_of("0123456789abcdef")==std::string::npos),"Invalid selected device UUID");
        const auto root=Parser(report.json).parse();const auto& devices=root.at("devices");Require(devices.kind==Json::Array,"Report devices unavailable");
        uint32_t matches=0,index=0;bool eligible=false;
        for(const auto& device:devices.array){
            if(device.at("vendorID").u64()!=identity.vendorID||device.at("deviceID").u64()!=identity.deviceID||device.at("driverVersion").u64()!=identity.driverVersion||device.at("name").str()!=identity.name)continue;
            const auto uuid=device.object.find("deviceUUID");
            if(!identity.deviceUUID.empty()&&(uuid==device.object.end()||uuid->second.kind!=Json::StringValue||uuid->second.str()!=identity.deviceUUID))continue;
            Require(device.at("index").u64()<=UINT32_MAX,"Report device index overflow");index=uint32_t(device.at("index").u64());eligible=device.at("renderEligible").kind==Json::Boolean&&device.at("renderEligible").text=="true";++matches;
        }
        Require(matches==1,matches?"Selected device identity ambiguous":"Selected device identity absent");Require(!requireRenderEligible||eligible,"Selected device failed static renderer admission");reportIndex=index;error.clear();return true;
    }catch(const std::exception& e){error=e.what();return false;}
}
